const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2024-11-01';
  const endDate = '2024-12-01';
  const threshold = 20000;

  // Define the administrative boundaries dataset
  const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');

  // Filter for Punjab and Haryana states in India
  const punjab = adminBoundaries.filter(ee.Filter.and(
    ee.Filter.eq('ADM0_NAME', 'India'),
    ee.Filter.eq('ADM1_NAME', 'Punjab')
  ));

  const haryana = adminBoundaries.filter(ee.Filter.and(
    ee.Filter.eq('ADM0_NAME', 'India'),
    ee.Filter.eq('ADM1_NAME', 'Haryana')
  ));

  // Combine the geometries
  const geometry = punjab.merge(haryana).union();

  // 2. Data Acquisition & Check
  // VIIRS Active Fire data. The question is about detections, so we count pixels.
  // The 'MaxFRP' band contains data for detected fires.
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterDate(startDate, endDate)
    .filterBounds(geometry)
    .select('MaxFRP');

  // Check if the collection is empty. This is expected for a future date.
  const collectionSize = viirsCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`Period: ${startDate} to ${endDate}`);
    console.log("Image Collection Size: 0");
    console.log("Reason: The requested date range is in the future. No data is available.");
    console.log("A"); // The number of fires (0) is less than 20,000.
    return;
  }

  // 3. Processing
  // Create a mosaic of all fire detections during the period.
  // We count the number of pixels that have a valid MaxFRP value.
  const fireImage = viirsCollection.mosaic().selfMask(); // selfMask keeps only pixels with data

  // 4. Calculation
  // Count the number of fire pixels.
  const fireCountDict = fireImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000, // VIIRS resolution is ~1km
    maxPixels: 1e9
  });

  const fireCount = fireCountDict.get('MaxFRP').getInfo();

  // 5. Validation & Final Answer
  console.log(`Period: ${startDate} to ${endDate}`);
  console.log(`VIIRS Image Count: ${collectionSize}`);

  if (fireCount === null) {
      console.log("Calculation failed: could not retrieve fire pixel count.");
      console.log("C3");
      return;
  }

  console.log(`Total Fire Detections (pixels): ${fireCount}`);
  console.log(`Threshold: < ${threshold}`);

  if (fireCount < threshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

